assert "test('lead reassignment transfers the old marketer’s pending program responsibility and preserves source credit',()=>{\n let {state,id}=lead();state=update(state,'building_fit',{status:'pending',owner:'u1',due:engine(state,'u0').T});\n state=execute(state,'u0',{op:'assign',expectedVersion:state.leads[0].version,args:[id,{rep:'u1'}]});\n assert.equal(state.leads[0].countyWorkflow.steps.building_fit.owner,'u1');assert.equal(state.leads[0].originRep,'u1');\n assert.throws(()=>execute(state,'u1',{op:'setCountyStep',expectedVersion:state.leads[0].version,args:[id,'building_fit',{status:'pending',owner:'u1',due:engine(state,'u0').T}]}),e=>e.status===404);\n});\n" in s
p.write_text(s.replace("test('lead reassignment transfers the old marketer’s pending program responsibility and preserves source credit',()=>{\n let {state,id}=lead();state=update(state,'building_fit',{status:'pending',owner:'u1',due:engine(state,'u0').T});\n state=execute(state,'u0',{op:'assign',expectedVersion:state.leads[0].version,args:[id,{rep:'u1'}]});\n assert.equal(state.leads[0].countyWorkflow.steps.building_fit.owner,'u1');assert.equal(state.leads[0].originRep,'u1');\n assert.throws(()=>execute(state,'u1',{op:'setCountyStep',expectedVersion:state.leads[0].version,args:[id,'building_fit',{status:'pending',owner:'u1',due:engine(state,'u0').T}]}),e=>e.status===404);\n});\n","test('lead reassignment transfers the old marketer’s pending program responsibility and preserves source credit',()=>{\n let {state,id}=lead();state=update(state,'building_fit',{status:'pending',owner:'u1',due:engine(state,'u0').T});\n state=execute(state,'u0',{op:'assign',expectedVersion:state.leads[0].version,args:[id,{rep:'u2'}]});\n assert.equal(state.leads[0].countyWorkflow.steps.building_fit.owner,'u2');assert.equal(state.leads[0].originRep,'u1');\n assert.throws(()=>execute(state,'u1',{op:'setCountyStep',expectedVersion:state.leads[0].version,args:[id,'building_fit',{status:'pending',owner:'u1',due:engine(state,'u0').T}]}),e=>e.status===404);\n});\n",1))

(r/"test/olivia-access.test.mjs").write_text("import test from 'node:test';import assert from 'node:assert/strict';import {createHmac,createHash,randomUUID} from 'node:crypto';import {mkdtempSync,rmSync} from 'node:fs';import {tmpdir} from 'node:os';import path from 'node:path';\nimport {initialState,execute,scoped,buildingAccess} from '../server/engine.mjs';import {createApplication} from '../server/index.mjs';import {seal} from '../server/security.mjs';\nfunction fixture(){const s=initialState(false);s.users.find(u=>u.id==='u2').buildingAccess='all';const seed=execute(s,'u0',{op:'createLead',createdId:'L_scope_template',args:[{first:'Synthetic',last:'Template',rep:'u1',building:'riverside',payer:'Private pay'}]});const template=seed.leads[0];s.leads=[];for(const building of ['riverside','pointe','hallmark','carrington'])for(const rep of ['u1','u2','u3','u0'])s.leads.push({...structuredClone(template),id:'L_'+building+'_'+rep,last:building+'_'+rep,building,rep,originRep:rep==='u3'?'u2':rep,files:[{id:'file_'+building+'_'+rep,name:'synthetic.txt'}]});s.tasks=s.leads.map(l=>({id:'task_'+l.id,text:l.last,rep:'u2',leadId:l.id,due:'2020-01-01'}));return s;}\ntest('Olivia sees only own and Morgan assigned leads outside Gaby buildings, overriding saved all access',()=>{const s=fixture(),before=JSON.stringify(s),o=scoped(s,'u2');assert.equal(o.buildings.length,16);assert.deepEqual(o.leads.map(l=>l.id),['L_riverside_u1','L_riverside_u2']);assert.equal(o.tasks.length,2);assert.equal(o.users.find(u=>u.id==='u2').buildingAccess.length,16);for(const b of ['hallmark','pointe','carrington'])assert.ok(!buildingAccess(s,'u2').includes(b));assert.equal(scoped(s,'u3').leads.length,12);assert.equal(scoped(s,'u1').leads.length,16);assert.equal(scoped(s,'u0').leads.length,16);assert.equal(JSON.stringify(s),before);});\ntest('Olivia edits own allowed leads, views Morgan without general editing, and cannot mutate hidden records',()=>{let s=fixture();s=execute(s,'u2',{op:'setTemp',expectedVersion:1,args:['L_riverside_u2','cold']});for(const id of ['L_riverside_u1','L_riverside_u3','L_hallmark_u2'])assert.throws(()=>execute(s,'u2',{op:'setTemp',expectedVersion:1,args:[id,'cold']}),e=>e.status===404);assert.throws(()=>execute(s,'u2',{op:'addTask',args:[{leadId:'L_hallmark_u2',text:'hidden'}]}),e=>e.status===404);assert.throws(()=>execute(s,'u2',{op:'createLead',createdId:'L_new_forbidden',args:[{first:'Synthetic',last:'Forbidden',rep:'u2',building:'hallmark'}]}),e=>e.status===403);assert.throws(()=>execute(s,'u0',{op:'assign',expectedVersion:2,args:['L_riverside_u2',{building:'pointe'}]}),e=>e.status===422);});\ntest('Olivia HTTP state, exports, direct files and packet URLs enforce both owner and building restrictions',async()=>{const dir=mkdtempSync(path.join(tmpdir(),'olivia-scope-')),secret='scope-test-secret',fileKey='scope-test-file-key',csrf='scope-csrf',app=await createApplication({schedule:false,env:{NODE_ENV:'test',APP_MODE:'live',PHI_APPROVED:'true',DATABASE_URL:'',SQLITE_PATH:path.join(dir,'db'),SESSION_SECRET:secret,FILE_ENCRYPTION_KEY:fileKey}});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port,headers={Cookie:'tl_session=olivia',Origin:origin,'X-CSRF-Token':csrf,'Content-Type':'application/json'};try{const s=fixture();await app.store.query('UPDATE app_state SET data=$1 WHERE id=$2',[JSON.stringify(s),'main']);await app.store.query('INSERT INTO sessions (token_hash,user_id,expires_at,csrf) VALUES ($1,$2,$3,$4)',[createHmac('sha256',secret).update('olivia').digest('hex'),'u2',Date.now()+60000,csrf]);for(const l of s.leads)await app.store.query('INSERT INTO files (id,user_id,name,mime,size,sha256,ciphertext,created_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)',[l.files[0].id,'u0','synthetic.txt','text/plain',9,'test',seal(Buffer.from('synthetic'),createHash('sha256').update(fileKey).digest()),new Date().toISOString()]);const response=await (await fetch(origin+'/api/state',{headers})).json();assert.equal(response.state.leads.length,2);const exported=await (await fetch(origin+'/api/export',{headers})).text();for(const l of s.leads){const allowed=l.building==='riverside'&&['u1','u2'].includes(l.rep);assert.equal(exported.includes(l.id),allowed,l.id);assert.equal((await fetch(origin+'/api/files/'+l.files[0].id,{headers})).status,allowed?200:404);if(!allowed){assert.equal((await fetch(origin+'/api/leads/'+l.id+'/libertana/packet.pdf',{headers})).status,404);assert.equal((await fetch(origin+'/api/commands',{method:'POST',headers,body:JSON.stringify({id:randomUUID(),op:'setTemp',expectedVersion:1,args:[l.id,'cold']})})).status,404);}}}finally{await app.close();rmSync(dir,{recursive:true,force:true});}});\n")
